package kz.zani.mobile
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
@OptIn(ExperimentalCoroutinesApi::class)
class InboxLifecycleTest {
    private fun fixture(n:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$n.json")!!.bufferedReader().use {it.readText()}
    private fun context(o:JSONObject)=InboxConversationFilesContext(o.getInt("business"),o.getInt("conversation"),o.getInt("epoch"),o.getInt("revision"))
    private fun files()=APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files")))
    private fun source()=APIInboxLifecycleRepository(FixtureInboxLifecycleReadTransport.fromJSON(fixture("inbox-lifecycle")))
    private class Held(override val grants:List<SyntheticInboxLifecycleGrant>):SyntheticInboxLifecyclePort {val attempts=mutableListOf<InboxLifecycleAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxLifecycleOutcome>>();override suspend fun execute(a:InboxLifecycleAttempt):SyntheticInboxLifecycleOutcome {attempts+=a;return CompletableDeferred<SyntheticInboxLifecycleOutcome>().also {pending+=it}.await()}}
    @Test fun strictSourcePlain200BothActionsAndNoReasonEchoOrInferredReopenFlags()=runTest {
        val d=JSONObject(fixture("inbox-lifecycle"));val c=context(d.getJSONObject("context"));val cases=d.getJSONArray("source_cases");for(i in 0 until cases.length()){val x=cases.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLifecycleSource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val f=FixtureInboxLifecyclePort.fromJSON(fixture("inbox-lifecycle"));val s=InboxLifecycleSource.decode(d.getString("source_json"),c)!!;val auth=f.grants[0].authorization(c)!!;val receipts=d.getJSONArray("receipt_cases");for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);val action=InboxLifecycleAction.entries.single {it.wire==x.getString("action")};val l=InboxLifecycleLedger();val a=l.begin(InboxLifecycleReview(s,auth,action,1))!!;val result=InboxLifecycleReceipt.decode(x.getString("response_json"),a);assertEquals(x.getString("name"),x.getBoolean("valid"),result!=null);l.complete(a,SyntheticInboxLifecycleOutcome.Response(200,x.getString("response_json")));assertEquals(if(result==null)InboxLifecyclePhase.UNKNOWN else InboxLifecyclePhase.RESPONSE,l.visible(auth)!!.phase);assertEquals(a,l.records[0].attempt)}
        for(action in InboxLifecycleAction.entries){val l=InboxLifecycleLedger();val r=InboxLifecycleReview(s,auth,action,2);val a=l.begin(r)!!;assertEquals("{}",a.preparedBody());assertEquals(0,JSONObject(a.preparedBody()).length());assertEquals("/api/inbox/conversations/901/${action.wire}/",a.path);assertTrue(a.query.isEmpty());assertTrue(a.headers.isEmpty());assertNull(l.begin(r));assertFalse(l.acknowledge(auth,l.visible(auth)!!));l.complete(a,f.execute(a));val result=l.visible(auth)!!;assertEquals(InboxLifecyclePhase.RESPONSE,result.phase);assertEquals(if(action==InboxLifecycleAction.CLOSE)"closed"else "open",result.result!!.source.status);if(action==InboxLifecycleAction.REOPEN){assertFalse(result.result.source.botEnabled);assertTrue(result.result.source.handoffRequired)};assertEquals(s,result.attempt.review.source);assertTrue(l.acknowledge(auth,result))}
        val l=InboxLifecycleLedger();val r=InboxLifecycleReview(s,auth,InboxLifecycleAction.REOPEN,3);val a=l.begin(r)!!;l.complete(a,SyntheticInboxLifecycleOutcome.Unknown);val u=l.visible(auth)!!;val next=c.copy(epoch=2,revision=2);val na=f.grants[0].authorization(next)!!;val matching=InboxLifecycleSource.decode(d.getString("reopen_response_json"),next)!!;assertEquals(u,l.visible(na));assertFalse(l.acknowledge(na,u));assertNull(l.begin(InboxLifecycleReview(matching,na,InboxLifecycleAction.CLOSE,4)));assertEquals(a,l.records[0].attempt);val other=SyntheticInboxLifecycleGrant(101,901,6002,true).authorization(next)!!;assertNull(l.visible(other));assertTrue(l.blocked(101,901));assertFalse(l.blocked(202,951))
        for(g in listOf(SyntheticInboxLifecycleGrant(101,901,5001,false),SyntheticInboxLifecycleGrant(202,901,5001,true),SyntheticInboxLifecycleGrant(101,951,5001,true),SyntheticInboxLifecycleGrant(101,901,0,true)))assertNull(g.authorization(c))
        for(status in listOf(201,400,403,409,500)){val x=InboxLifecycleLedger();val a=x.begin(r)!!;x.complete(a,SyntheticInboxLifecycleOutcome.Response(status,d.getString("reopen_response_json")));assertEquals(InboxLifecyclePhase.UNKNOWN,x.visible(auth)!!.phase);assertFalse(x.acknowledge(auth,x.visible(auth)!!))}
    }
    @Test fun actualParentPendingKnownUnknownRereadABAAndAvailableSiblingBarriers()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxLifecyclePort.fromJSON(fixture("inbox-lifecycle"));val held=Held(f.grants);val read=APIReadRepository(ReadTransport {q->val n=if(q.path=="/api/mobile/v1/inbox/")"inbox-${q.query["business"]}"else "inbox-${q.query["business"]}-${q.path.trimEnd('/').substringAfterLast('/')}";ReadResponse(200,fixture(n))})
        val m=InboxViewModel(read,files=files(),assignmentRead=APIInboxSelfAssignmentRepository(FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment"))),assignmentSubmission=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment")),markerRead=APIInboxReadMarkerRepository(FixtureInboxReadMarkerReadTransport.fromJSON(fixture("inbox-read-markers"))),markerSubmission=FixtureInboxReadMarkerPort.fromJSON(fixture("inbox-read-markers")),priorityRead=APIInboxPriorityRepository(FixtureInboxPriorityReadTransport.fromJSON(fixture("inbox-priority"))),prioritySubmission=FixtureInboxPriorityPort.fromJSON(fixture("inbox-priority")),lifecycleRead=source(),lifecycleSubmission=held)
        try {m.load(101,521);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val c=m.fileMetadata!!;m.openFiles(m.filesEntryControl);assertNull(c.lifecycleSource);assertFalse(c.canPrepareLifecycle);c.loadLifecycle(c.control);c.loadAssignment(c.control);c.loadMarker(c.control);c.loadPriority(c.control);assertTrue(c.canPrepareAssignment);assertTrue(c.canPrepareMarker);assertTrue(c.canChoosePriority);val old=c.control;c.prepareLifecycle(InboxLifecycleAction.CLOSE,c.control);val r=c.lifecycleReview!!;val ctrl=c.control;c.backLifecycle(old);c.prepareMarker(InboxReadMarkerAction.READ,c.control);c.prepareAssignment(c.control);c.choosePriority(InboxPriorityValue.HIGH,c.control);c.loadLifecycle(c.control);assertEquals(r,c.lifecycleReview);assertNull(c.markerReview);assertNull(c.assignmentReview);assertNull(c.selectedPriorityValue);assertTrue(c.canSubmitLifecycle);val job=launch {c.submitLifecycle(r,ctrl)};runCurrent();val pending=c.lifecycleRecord!!;c.submitLifecycle(r,c.control);c.acknowledgeLifecycle(pending,c.control);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);assertFalse(c.canLoadPriority);assertFalse(c.canLoadMarker);assertFalse(c.canLoadLifecycle);m.closeFiles(m.filesPresentationControl);m.openReply(m.reply.state.context!!,m.control);m.openHandoff(m.handoff.entryControl,m.control);assertNull(m.reply.control);assertNull(m.handoff.control);m.openFiles(m.filesEntryControl);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val result=c.lifecycleRecord!!;assertEquals(InboxLifecyclePhase.RESPONSE,result.phase);assertEquals("closed",result.result!!.source.status);assertFalse(result.result.source.botEnabled);assertFalse(result.result.source.handoffRequired);assertEquals(original,m.state.thread);c.acknowledgeLifecycle(result,ctrl);assertEquals(result,c.lifecycleRecord);c.acknowledgeLifecycle(result,c.control);c.loadLifecycle(c.control);c.prepareLifecycle(InboxLifecycleAction.REOPEN,c.control);val ur=c.lifecycleReview!!;val uc=c.control;val uj=launch {c.submitLifecycle(ur,uc)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("synthetic failure"));uj.join();val unknown=c.lifecycleRecord!!;c.loadLifecycle(c.control);c.acknowledgeLifecycle(unknown,c.control);c.prepareLifecycle(InboxLifecycleAction.CLOSE,c.control);c.prepareMarker(InboxReadMarkerAction.UNREAD,c.control);c.prepareAssignment(c.control);c.choosePriority(InboxPriorityValue.HIGH,c.control);assertEquals("open",c.lifecycleSource!!.status);assertEquals(unknown,c.lifecycleRecord);assertNull(c.lifecycleReview);assertNull(c.markerReview);assertNull(c.assignmentReview);assertNull(c.selectedPriorityValue);assertEquals(InboxLifecycleAction.REOPEN,unknown.attempt.review.action);m.closeFiles(m.filesPresentationControl);m.load(202,522);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);c.loadLifecycle(c.control);assertNull(c.lifecycleRecord);assertTrue(c.canPrepareLifecycle);m.closeFiles(m.filesPresentationControl);m.load(101,523);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);c.loadLifecycle(c.control);assertEquals(unknown,c.lifecycleRecord);assertFalse(c.canPrepareLifecycle)
        } finally {m.viewModelScope.cancel();Dispatchers.resetMain()}
    }
    @Test fun cancellationRejectionDefaultPortAndLateOwnerReadAndCommand()=runTest {
        val f=FixtureInboxLifecyclePort.fromJSON(fixture("inbox-lifecycle"));val held=Held(f.grants);val ac=InboxConversationFilesContext(101,901,524,1);val bc=InboxConversationFilesContext(202,951,525,1);val m=InboxConversationFilesModel(files(),lifecycleRead=source(),lifecyclePort=held);m.commandsBlocked={false};m.bind(ac);m.open(m.control);m.loadLifecycle(m.control);m.prepareLifecycle(InboxLifecycleAction.CLOSE,m.control);val r=m.lifecycleReview!!;val ctrl=m.control;val j=launch {m.submitLifecycle(r,ctrl)};runCurrent();held.pending[0].complete(SyntheticInboxLifecycleOutcome.RejectedWithoutWrite);j.join();val rejected=m.lifecycleRecord!!;assertEquals(InboxLifecyclePhase.REJECTED,rejected.phase);m.acknowledgeLifecycle(rejected,m.control);m.prepareLifecycle(InboxLifecycleAction.REOPEN,m.control);val cr=m.lifecycleReview!!;val cc=m.control;val cj=launch {m.submitLifecycle(cr,cc)};runCurrent();cj.cancelAndJoin();assertEquals(InboxLifecyclePhase.UNKNOWN,m.lifecycleRecord!!.phase);assertEquals(cr,m.lifecycleRecord!!.attempt.review)
        val np=InboxConversationFilesModel(files(),lifecycleRead=source());np.commandsBlocked={false};np.bind(ac);np.open(np.control);np.loadLifecycle(np.control);np.prepareLifecycle(InboxLifecycleAction.CLOSE,np.control);assertNotNull(np.lifecycleSource);assertFalse(np.canPrepareLifecycle);assertNull(np.lifecycleReview)
        val lp=Held(f.grants);val late=InboxConversationFilesModel(files(),lifecycleRead=source(),lifecyclePort=lp);late.commandsBlocked={false};late.bind(ac);late.open(late.control);late.loadLifecycle(late.control);late.prepareLifecycle(InboxLifecycleAction.CLOSE,late.control);val lr=late.lifecycleReview!!;val lc=late.control;val job=launch {late.submitLifecycle(lr,lc)};runCurrent();val a=lp.attempts[0];late.close(late.presentation);late.bind(bc);late.open(late.control);late.loadLifecycle(late.control);val before=late.control;val beforeSource=late.lifecycleSource;lp.pending[0].complete(f.execute(a));job.join();assertEquals(before,late.control);assertEquals(beforeSource,late.lifecycleSource);assertNull(late.lifecycleRecord);assertEquals(1,late.retainedLifecycleCount)
        val deferred=CompletableDeferred<InboxLifecycleSource>();val repo=object:InboxLifecycleRepository {override suspend fun source(c:InboxConversationFilesContext)=deferred.await()};val lateRead=InboxConversationFilesModel(files(),lifecycleRead=repo,lifecyclePort=f);lateRead.bind(ac);lateRead.open(lateRead.control);val old=lateRead.control;val readJob=launch {lateRead.loadLifecycle(old)};runCurrent();lateRead.close(lateRead.presentation);lateRead.bind(bc);lateRead.open(lateRead.control);val current=lateRead.control;deferred.complete(source().source(ac));readJob.join();assertEquals(current,lateRead.control);assertNull(lateRead.lifecycleSource);assertFalse(lateRead.lifecycleLoading)
    }
}
